class NumArray {
    private int[] bit;
    private int[] nums;

    public NumArray(int[] nums) {
        this.nums = nums.clone();
        bit = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            add(i + 1, nums[i]);
        }
    }

    public void update(int index, int val) {
        int delta = val - nums[index];
        nums[index] = val;
        add(index + 1, delta);
    }

    public int sumRange(int left, int right) {
        return prefix(right + 1) - prefix(left);
    }

    private void add(int index, int delta) {
        for (int i = index; i < bit.length; i += i & -i) {
            bit[i] += delta;
        }
    }

    private int prefix(int count) {
        int sum = 0;
        for (int i = count; i > 0; i -= i & -i) {
            sum += bit[i];
        }
        return sum;
    }
}

class NumArray {
    private int n;
    private int[] tree;

    public NumArray(int[] nums) {
        n = nums.length;
        tree = new int[n * 4];
        build(1, 0, n - 1, nums);
    }

    public void update(int index, int val) {
        update(1, 0, n - 1, index, val);
    }

    public int sumRange(int left, int right) {
        return query(1, 0, n - 1, left, right);
    }

    private void build(int node, int start, int end, int[] nums) {
        if (start == end) {
            tree[node] = nums[start];
            return;
        }
        int mid = start + (end - start) / 2;
        build(node * 2, start, mid, nums);
        build(node * 2 + 1, mid + 1, end, nums);
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    private void update(int node, int start, int end, int index, int val) {
        if (start == end) {
            tree[node] = val;
            return;
        }
        int mid = start + (end - start) / 2;
        if (index <= mid) {
            update(node * 2, start, mid, index, val);
        } else {
            update(node * 2 + 1, mid + 1, end, index, val);
        }
        tree[node] = tree[node * 2] + tree[node * 2 + 1];
    }

    private int query(int node, int start, int end, int left, int right) {
        if (right < start || end < left) {
            return 0;
        }
        if (left <= start && end <= right) {
            return tree[node];
        }
        int mid = start + (end - start) / 2;
        return query(node * 2, start, mid, left, right)
                + query(node * 2 + 1, mid + 1, end, left, right);
    }
}

class NumArray {
    private int n;
    private int[] tree;

    public NumArray(int[] nums) {
        n = nums.length;
        tree = new int[n * 2];
        for (int i = 0; i < n; i++) {
            tree[n + i] = nums[i];
        }
        for (int i = n - 1; i > 0; i--) {
            tree[i] = tree[i * 2] + tree[i * 2 + 1];
        }
    }

    public void update(int index, int val) {
        int pos = index + n;
        tree[pos] = val;
        for (pos /= 2; pos > 0; pos /= 2) {
            tree[pos] = tree[pos * 2] + tree[pos * 2 + 1];
        }
    }

    public int sumRange(int left, int right) {
        int sum = 0;
        left += n;
        right += n;
        while (left <= right) {
            if ((left & 1) == 1) {
                sum += tree[left++];
            }
            if ((right & 1) == 0) {
                sum += tree[right--];
            }
            left /= 2;
            right /= 2;
        }
        return sum;
    }
}

class NumArray {
    private int[] nums;
    private int[] blockSum;
    private int blockSize;

    public NumArray(int[] nums) {
        this.nums = nums.clone();
        blockSize = (int) Math.ceil(Math.sqrt(nums.length));
        int blocks = (nums.length + blockSize - 1) / blockSize;
        blockSum = new int[blocks];
        for (int i = 0; i < nums.length; i++) {
            blockSum[i / blockSize] += nums[i];
        }
    }

    public void update(int index, int val) {
        int block = index / blockSize;
        blockSum[block] += val - nums[index];
        nums[index] = val;
    }

    public int sumRange(int left, int right) {
        int sum = 0;
        int startBlock = left / blockSize;
        int endBlock = right / blockSize;
        if (startBlock == endBlock) {
            for (int i = left; i <= right; i++) {
                sum += nums[i];
            }
            return sum;
        }
        int endOfStartBlock = Math.min(nums.length - 1, (startBlock + 1) * blockSize - 1);
        for (int i = left; i <= endOfStartBlock; i++) {
            sum += nums[i];
        }
        for (int block = startBlock + 1; block < endBlock; block++) {
            sum += blockSum[block];
        }
        for (int i = endBlock * blockSize; i <= right; i++) {
            sum += nums[i];
        }
        return sum;
    }
}

class NumArray {
    private int[] nums;

    public NumArray(int[] nums) {
        this.nums = nums.clone();
    }

    public void update(int index, int val) {
        nums[index] = val;
    }

    public int sumRange(int left, int right) {
        int sum = 0;
        for (int i = left; i <= right; i++) {
            sum += nums[i];
        }
        return sum;
    }
